import { useEffect, useState, useRef } from 'react'; import { useParams } from 'react-router-dom'; import api from '../services/api'; import { connectSocket, getSocket } from '../services/socket'; export default function ChatView(){ const {id}=useParams(); const [msgs,setMsgs]=useState([]); const [text,setText]=useState(''); const ref=useRef(); const myId=(()=>{ try{ return JSON.parse(atob(localStorage.getItem('kss_token').split('.')[1])).id }catch{ return null } })(); useEffect(()=>{ api.get('/api/messages/'+id).then(r=>setMsgs(r.data)); const s=connectSocket(); s.emit('join_conversation',id); s.on('new_message',m=>{ if(m.conversation_id===id) setMsgs(p=>[...p,m]) }); return()=>{ const so=getSocket(); if(so) so.off('new_message') } },[id]); useEffect(()=>ref.current?.scrollIntoView({behavior:'smooth'}),[msgs]); const send=()=>{ if(!text.trim()) return; getSocket().emit('send_message',{conversationId:id,text}); setText('') }; return <div style={{maxWidth:500,margin:'0 auto',background:'#eef2f7',minHeight:'100vh',display:'flex',flexDirection:'column'}}><div style={{background:'#0a4da1',color:'white',padding:12}}><a href="/chats" style={{color:'white',marginRight:10}}>← Back</a> Chat</div><div style={{flex:1,padding:12,overflowY:'auto'}}>{msgs.map(m=><div key={m.id} className={'bubble '+(m.sender_id===myId?'me':'other')}>{m.text}<br/><small style={{fontSize:10}}>{new Date(m.created_at).toLocaleTimeString()}</small></div>)}<div ref={ref}></div></div><div style={{display:'flex',padding:8,background:'white'}}><input value={text} onChange={e=>setText(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="Type message"/><button style={{width:80,marginLeft:8}} onClick={send}>Send</button></div></div> }
